import React from 'react';

/**
 * HEADER CON NAVEGACIÓN FUNCIONAL
 *
 * CAMBIOS:
 * 1. Agregamos la prop onLoginClick
 * 2. Eliminamos el <a href="./login.html">
 * 3. Agregamos onClick al botón
 */
const Header = ({ onLoginClick }) => {
    return (
        <div className="header">
            <div className="contact-info">
                <h1>☏</h1>
                <div className="contact-text">
                    <h3>Contactanos</h3>
                    <p>3144368571</p>
                </div>
            </div>

            <center>
                <div className="logo">
                    FoamWash
                    <span style={{ fontSize: '0.7em' }}>LG</span>
                </div>
            </center>

            <button className="login-btn" onClick={onLoginClick}>Iniciar sesión</button>
        </div>
    );
};

export default Header;
